interface DiscountStrategy {
    long apply(long amountCents);
}

final class NoDiscount implements DiscountStrategy {
    public long apply(long amountCents) { return amountCents; }
}

final class FlatPercentOff implements DiscountStrategy {
    private final int percent;
    FlatPercentOff(int percent) { this.percent = percent; }
    public long apply(long amountCents) {
        return amountCents * (100L - percent) / 100L;
    }
}

final class PriceCalculator {
    private final DiscountStrategy strategy;
    PriceCalculator(DiscountStrategy strategy) { this.strategy = strategy; }
    long total(long amountCents) { return strategy.apply(amountCents); }
}

import java.util.*;

interface PriceListener {
    void onPrice(String symbol, long priceCents);
}

final class Ticker {
    private final List<PriceListener> listeners = new ArrayList<>();
    void subscribe(PriceListener l) { listeners.add(l); }
    void unsubscribe(PriceListener l) { listeners.remove(l); }
    void publish(String symbol, long priceCents) {
        // Snapshot: a listener may unsubscribe during notification.
        for (PriceListener l : List.copyOf(listeners)) {
            l.onPrice(symbol, priceCents);
        }
    }
}
